# Let me carefully construct the solution using verified code
# I'll compute each quadrant's transformation step by step

grid = [
    [1, 6, 2, 4, 1],
    [3, 9, 9, 9, 9],
    [9, 9, 3, 9, 9],
    [0, 2, 9, 5, 4],
    [7, 9, 9, 9, 9]
]

def rotate90(g):
    """Rotate grid 90° clockwise"""
    n, m = len(g), len(g[0])
    return [[g[n-1-c][r] for c in range(n)] for r in range(m)]

def rotate_k(g, k):
    """Rotate grid k times by 90° clockwise"""
    k = k % 4
    result = g[:]
    for _ in range(k):
        result = rotate90(result[:])
    return result

# For 4×4 extraction from top-left
n, m = len(grid), len(grid[0])
split = n // 2  # = 2 for 5×5, giving 2×2 for TL

tl_in = [row[:split] for row in grid[:split]]
tr_in = [row[split:] for row in grid[:split]]
bl_in = [row[:split] for row in grid[split:]]
br_in = [row[split:] for row in grid[split:]]

print(f"Extraction split: {split}")
print(f"TL input ({len(tl_in)}×{len(tl_in[0]) if tl_in else 0}):")
for row in tl_in:
    print(row)

print(f"\nTR input ({len(tr_in)}×{len(tr_in[0]) if tr_in else 0}):")
for row in tr_in:
    print(row)

print(f"\nBL input ({len(bl_in)}×{len(bl_in[0]) if bl_in else 0}):")
for row in bl_in:
    print(row)

print(f"\nBR input ({len(br_in)}×{len(br_in[0]) if br_in else 0}):")
for row in br_in:
    print(row)

# Compute rotated versions
tl_rot = rotate_k(tl_in, 0)
tr_rot = rotate_k(tr_in, 1)
bl_rot = rotate_k(bl_in, 3)
br_rot = rotate_k(br_in, 2)

print("\n=== Rotated Quadrants ===")
print(f"TL (0°) - {len(tl_rot)}×{len(tl_rot[0]) if tl_rot else 0}:")
for row in tl_rot:
    print(row)

print(f"\nTR (90°) - {len(tr_rot)}×{len(tr_rot[0]) if tr_rot else 0}:")
for row in tr_rot:
    print(row)

print(f"\nBL (270°) - {len(bl_rot)}×{len(bl_rot[0]) if bl_rot else 0}:")
for row in bl_rot:
    print(row)

print(f"\nBR (180°) - {len(br_rot)}×{len(br_rot[0]) if br_rot else 0}:")
for row in br_rot:
    print(row)

# Now construct 5×5 output
# Drawings of TL, TR, BL, BR at their positions with their rotated content

output = [[0]*5 for _ in range(5)]

# TL at (0,0): rows 0-1, cols 0-1
for r in range(len(tl_rot)):
    for c in range(len(tl_rot[0])):
        if r < 5 and c < 5:
            output[r][c] = tl_rot[r][c]

# TR at (0,2): rows 0-2, cols 2-3
for r in range(len(tr_rot)):
    for c in range(len(tr_rot[0])):
        if r < 5 and c+2 < 5:
            output[r][c+2] = tr_rot[r][c]

# BL at (2,0): rows 2-3, cols 0-2
for r in range(len(bl_rot)):
    for c in range(len(bl_rot[0])):
        if r+2 < 5 and c < 5:
            output[r+2][c] = bl_rot[r][c]

# BR at (2,2): rows 2-4, cols 2-4
for r in range(len(br_rot)):
    for c in range(len(br_rot[0])):
        if r+2 < 5 and c+2 < 5:
            output[r+2][c+2] = br_rot[r][c]

print("\n=== Final 5×5 Output ===")
for row in output:
    print(row)

# Verify each cell's origin
print("\n=== Verification ===")
print("TL cells (0,0),(0,1),(1,0),(1,1):")
for r in range(2):
    for c in range(2):
        print(f"  ({r},{c}) = {output[r][c]}")

print("\nTR cells (0,2),(0,3),(1,2),(1,3),(2,2),(2,3):")
for r in range(3):
    for c in range(2):
        print(f"  ({r},{c+2}) = {output[r][c+2]}")

print("\nBL cells (2,0),(2,1),(2,2),(3,0),(3,1),(3,2):")
for r in range(2):
    for c in range(3):
        val = output[r+2][c]
        print(f"  ({r+2},{c}) = {val}")

print("\nBR cells (2,2),(2,3),(2,4),(3,2),(3,3),(3,4),(4,2),(4,3),(4,4):")
for r in range(3):
    for c in range(3):
        print(f"  ({r+2},{c+2}) = {output[r+2][c+2]}")

# Request demos to understand the pattern
action = {"action": "request_demos"}
print(action)
